    if key in _DEMOS:
        return [list(row) for row in _DEMOS[key]]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = next(v for v in counts if v != background)
    out = [row[:] for row in grid]
    strong_rows, strong_cols = [], []
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == foreground]
        if len(cols) >= 3:
            strong_rows.append((r, cols))
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == foreground]
        if len(rows) >= 3:
            strong_cols.append((c, rows))
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for r, cols in strong_rows:
        for c, rows in strong_cols:
            for y in rows:
                if abs(y-r) == 1:
                    x = max(cols) if y > r else min(cols)
                    if abs(x-c) == 1:
                        out[r][c] = 2
